    mk=sorted({r for r,c in [(r,c) for r in range(H) for c in range(W) if g[r][c]==5]} - rs)
    out=[row[:] for row in g]
    for r in mk:
        for c in range(tc+1,te+1):
            out[r][c]=T[(tile_rows[0]-r)%th][c-(tc+1)]
    return out

